4e2a\\u6838\\u5fc3\\u89c2\\u70b9\\uff0c3\\u20135 \\u6761\\u8981\\u70b9\\n4. **\\u6570\\u636e\\u9875**\\uff1a\\u4e3a\\u56fe\\u8868/\\u56fe\\u5f62\\u63d0\\u4f9b\\u6e05\\u6670\\u7684\\u89c6\\u89c9\\u5316\\u63cf\\u8ff0\\n5. **\\u7ed3\\u8bba\\u9875**\\uff1a\\u5173\\u952e\\u8981\\u70b9\\u4e0e\\u884c\\u52a8\\u53f7\\u53ec\\n6. **\\u81f4\\u8c22\\u9875**\\uff1a\\u7ed3\\u675f\\u8bed + \\u8054\\u7cfb\\u65b9\\u5f0f\\n\\n## \\u4e8c\\u3001\\u5185\\u5bb9\\u63d0\\u53d6\\u89c4\\u5219\\n- \\u8bc6\\u522b\\u6e90\\u5185\\u5bb9\\u7684\\u5173\\u952e\\u4e3b\\u9898\\u4e0e\\u6838\\u5fc3\\u89c2\\u70b9\\n- \\u5c06\\u6bb5\\u843d\\u538b\\u7f29\\u4e3a\\u7b80\\u660e\\u8981\\u70b9\\uff08\\u6bcf\\u6761 \\u226410 \\u5b57\\uff09\\n- \\u4e3a\\u6bcf\\u9875\\u521b\\u5efa\\u6e05\\u6670\\u3001\\u884c\\u52a8\\u5bfc\\u5411\\u7684\\u6807\\u9898\\n- \\u751f\\u6210\\u6f14\\u8bb2\\u8005\\u5907\\u6ce8\\uff08\\u63d0\\u4f9b\\u989d\\u5916\\u4e0a\\u4e0b\\u6587\\uff09\\n- \\u5728\\u9002\\u5f53\\u4f4d\\u7f6e\\u5efa\\u8bae\\u56fe\\u7247/\\u89c6\\u89c9\\u5143\\u7d20\\n- \\u4fdd\\u6301\\u903b\\u8f91\\u6d41\\u7545\\u4e0e\\u53d9\\u4e8b\\u7ed3\\u6784\\n\\n## \\u4e09\\u3001\\u8f93\\u51fa\\u683c\\u5f0f\\n\\u6bcf\\u9875\\u8f93\\u51fa\\u5305\\u542b\\uff1a\\n```\\n{\\n  \\"slide_type\\": \\"title|content|image|section|data|conclusion\\",\\n  \\"title\\": \\"\\u9875\\u9762\\u6807\\u9898\\",\\n  \\"subtitle\\": \\"\\u53ef\\u9009\\u526f\\u6807\\u9898\\",\\n  \\"bullets\\": [\\"\\u8981\\u70b91\\", \\"\\u8981\\u70b92\\", \\"\\u8981\\u70b93\\"],\\n  \\"speaker_notes\\": \\"\\u6f14\\u8bb2\\u8005\\u8865\\u5145\\u4e0a\\u4e0b\\u6587\\",\\n  \\"visual_suggestion\\": \\"\\u5efa\\u8bae\\u7684\\u89c6\\u89c9/\\u56fe\\u8868\\u63cf\\u8ff0\\"\\n}\\n```\\n\\n---\\n\\n## \\u56db\\u3001\\u65b0\\u589e\\u786c\\u6027\\u8981\\u6c42\\uff08Updated Rules\\uff09\\n\\n### 1\\ufe0f\\u20e3 \\u8f93\\u51fa HTML\\uff0c\\u652f\\u6301\\u7ffb\\u9875\\n- \\u6bcf\\u4e00\\u9875\\u5fc5\\u987b\\u662f**\\u72ec\\u7acb\\u7684 HTML \\u6587\\u4ef6**\\uff08\\u81ea\\u5305\\u542b 