108	graphindex_chat	LLM-semantic-routed chat with project documents (Phase 9)	research	\N	{"model": "minimax-m3", "tools": [], "skills": [], "backend": {"type": "state", "config": {}, "mappings": null}, "cli_tools": [], "subagents": [], "guardrails": {"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000}, "long_term_memory": false, "enable_auto_eviction": true, "enable_summarization": true}, "max_tokens": 8192, "middleware": [{"type": "todo_list", "config": {}, "enabled": true}], "modalities": null, "temperature": 0.0, "custom_tools": [], "native_tools": ["graphindex_list_docs", "graphindex_search", "graphindex_load", "graphindex_multi_doc_load"], "export_format": "standalone", "system_prompt": "You are **graphindex_chat** — a research assistant for the user's project documents.\\n\\nTools:\\n  - graphindex_list_docs(project_id) — list available doc names\\n  - graphindex_search(query, project_id) — semantic search to find relevant docs\\n  - graphindex_load(context_doc_id) — read full doc text\\n  - graphindex_multi_doc_load(query, project_id) — PREFERRED: semantic search + load in one call\\n\\nRULES:\\n  1. ALWAYS prefer graphindex_multi_doc_load over individual tools.\\n  2. When user says \\"this doc\\" / \\"this file\\" / \\"summarize\\" — immediately\\n     call graphindex_multi_doc_load and answer. Do NOT list docs first.\\n  3. Never include raw JSON or tool output in your response — use results internally.\\n  4. Answer in the user's language. Concise (2-4 paragraphs). Cite the doc name.", "include_docker": false, "use_deepagents": true, "include_chat_ui": true, "interrupt_after": null, "interrupt_before": null, "reasoning_effort": "low", "use_local_sandbox": false, "skill_router_model": null, "use_phase9_graphindex": true, "disable_memory_middleware": false, "enable_compiled_subagents": true}	[{"type": "todo_list", "enabled": true, "config": {}}]	[]	{"type": "state", "config": {}, "ma