129	2.1 TODO Demo	2.1 TODO Demo	Custom	\N	{"model": "minimax-m3", "temperature": 0.0, "max_tokens": 128000, "reasoning_effort": "medium", "modalities": null, "system_prompt": "                                                                                                               \\u2502\\n\\u2502  Based upon the user's request:                                                                                 \\u2502\\n\\u2502  1. Use the write_todos tool to create TODO at the start of a user request, per the tool description.           \\u2502\\n\\u2502  2. After you accomplish a TODO, use the read_todos to read the TODOs in order to remind yourself of the plan.  \\u2502\\n\\u2502  3. Reflect on what you've done and the TODO.                                                                   \\u2502\\n\\u2502  4. Mark you task as completed, and proceed to the next TODO.                                                   \\u2502\\n\\u2502  5. Continue this process until you have completed all TODOs.                                                   \\u2502\\n\\u2502                                                                                                                 \\u2502\\n\\u2502  IMPORTANT: Always create a research plan of TODOs and conduct research following the above guidelines for ANY  \\u2502\\n\\u2502  user request.                                                                                                  \\u2502\\n\\u2502  IMPORTANT: Aim to batch research tasks into a *single TODO* in order to minimize the number of TODOs you have  \\u2502\\n\\u2502  to keep track of.      ", "tools": [], "native_tools": ["reasoning_chain", "write_todos", "read_todos", "tavily_search", "web_search", "vfs_ls", "vfs_read_file", "vfs_write_file"], "cli_tools": [], "custom_tools": [], "use_deepagents": false, "use_phase9_graphindex": false, "enable_compiled_subagents": true, "use_local_sandbox": false, "middleware": [], "subagents": [], "backend": {"type": "state", "config": {}, "mappings": null}, "guardrails": {"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": false}, "skills": [], "skill_router_model": null, "disable_memory_middleware": false, "interrupt_before": null, "interrupt_after": null, "export_format": "standalone", "include_chat_ui": true, "include_docker": false}	[]	[]	{"type": "state", "config": {}, "mappings": null}	{"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": false}	{}	0	\N	1.0.0	t	f	2026-07-07 11:37:07.124992+08	2026-07-07 17:31:51.645094+08	1
137	2.3 sub agent	2.3 subagent	Custom	\N	{"model": "minimax-m3", "temperature": 0.3, "max_tokens": 128000, "reasoning_effort": "low", "modalities": null, "system_prompt": "You can delegate tasks to sub-agents.\\n\\n<Task>\\nYour role is to coordinate research by delegating specific research tasks to sub-agents.\\n</Task>\\n\\n<Available Tools>\\n1. **task(description, subagent_type)**: Delegate research tasks to specialized sub-agents\\n   - description: Clear, specific research question or task\\n   - subagent_type: Type of agent to use (e.g., \\"research-agent\\")\\n2. **Reasoning Chain**: Reflect on the results of each delegated task and plan next steps.\\n\\n**PARALLEL RESEARCH**: When you identify multiple independent research directions, make multiple **task** tool calls in a single response to enable parallel execution. Use at most 3 parallel agents per iteration.\\n</Available Tools>\\n\\n<Hard Limits>\\n**Task Delegation Budgets** (Prevent excessive delegation):\\n- **Bias towards focused research** - Use single agent for simple questions, multiple only when clearly beneficial\\n- **Stop when adequate** - Don't over-research; stop when you have sufficient information\\n- **Limit iterations** - Stop after 3 task delegations if you haven't found adequate sources\\n</Hard Limits>\\n\\n<Scaling Rules>\\n**Simple fact-finding, lists, and rankings** can use a single sub-agent\\n**Comparisons** can use a sub-agent for each element of the comparison\\n**Multi-faceted research** can use parallel agents for different aspects\\n\\n**Important Reminders:**\\n- Each **task** call creates a dedicated research agent with isolated context\\n- Sub-agents can't see each other's work - provide complete standalone instructions\\n- Use clear, specific language - avoid acronyms or abbreviations in task descriptions\\n</Scaling Rules>", "tools": [], "native_tools": ["task"], "cli_tools": [], "custom_tools": [], "use_deepagents": false, "use_phase9_graphindex": false, "enable_compiled_subagents": true, "use_local_sandbox": false, "middleware": [], "subagents": [{"name": "research-agent", "description": "Delegate research tasks to the sub-agent researcher. Only give this researcher one topic at a time.", "type": "dictionary", "model": "minimax-m3", "system_prompt": "You are a researcher. Research the topic provided to you. \\nImportant: make a single call to the web_search tool and use the result provided by the tool to answer the provided topic.", "tools": ["web_search", "tavily_search"], "middleware": [], "workflow_id": null, "workflow_config": null}], "backend": {"type": "state", "config": {}, "mappings": null}, "guardrails": {"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": false}, "skills": [], "skill_router_model": null, "disable_memory_middleware": false, "interrupt_before": null, "interrupt_after": null, "export_format": "standalone", "include_chat_ui": true, "include_docker": false}	[]	[{"name": "research-agent", "description": "Delegate research tasks to the sub-agent researcher. Only give this researcher one topic at a time.", "type": "dictionary", "template_id": null, "model": "minimax-m3", "system_prompt": "You are a researcher. Research the topic provided to you. \\nImportant: make a single call to the web_search tool and use the result provided by the tool to answer the provided topic.", "tools": ["web_search", "tavily_search"], "middleware": [], "interrupt_on": {}, "skills": [], "response_format": null, "workflow_id": null, "workflow_config": null}]	{"type": "state", "config": {}, "mappings": null}	{"interrupts": {}, "token_limits": {"max_total_tokens": 100000, "eviction_threshold": 80000, "summarization_threshold": 60000}, "enable_auto_eviction": true, "enable_summarization": true, "long_term_memory": false}	{}	0	\N	1.0.0	t	f	2026-07-07 22:50:56.791659+08	2026-07-07 23:2